              @change="validateSlaData('service_level')"
              :disabled="Boolean(slaActiveScreen.data)"
              maxlength="50"
            />
            <ErrorMessage :message="slaDataErrors.service_level" class="mt-2" />
          </div>
          <FormControl
            :type="'textarea'"
