            maxlength="140"
          />
        </div>
        <hr class="my-8" />
        <div>
          <div class="flex flex-col gap-1">
            <span class="text-lg font-semibold text-ink-gray-8">{{
              __("Assignment Conditions")
            }}</span>
            <span class="text-p-sm text-ink-gray-6">
              {{ __("Choose which tickets are affected by this policy.") }}
            </span>
          </div>
          <div class="mt-3">
            <div class="flex items-center justify-between">
              <Checkbox
                :label="__('Set as default SLA')"
                :model-value="slaData.default_sla"
                @update:model-value="toggleDefaultSla"
                class="text-ink-gray-6 text-base font-medium"
              />
              <div
                v-if="isOldSla && slaActiveScreen.data && !slaData.default_sla"
              >
                <Popover trigger="hover" :hoverDelay="0.25" placement="top-end">
                  <template #target>
                    <div
                      class="text-sm text-ink-gray-6 flex gap-1 cursor-default"
                    >
                      {{ __("Old Conditions") }}
                      <FeatherIcon name="info" class="size-4" />
                    </div>
                  </template>
                  <template #body-main>
                    <div
                      class="text-sm text-ink-gray-6 p-2 bg-surface-white rounded-md max-w-96 text-wrap whitespace-pre-wrap leading-5"
                    >
                      <code>{{ slaData.condition }}</code>
                    </div>
                  </template>
                </Popover>
              </div>
            </div>
            <div class="mt-5" v-if="!slaData.default_sla">
              <div
                class="flex flex-col gap-3 items-center text-center text-ink-gray-7 text-sm mb-2 border border-outline-gray-2 rounded-md p-3 py-4"
                v-if="!useNewUI"
              >
                <span class="text-p-sm">
                  <!-- //// Neoffice — one sentence cut around the link: only its first fragment went through __() and the rest stayed in plain English. One msgid with {0} where the link goes, halves read back from the translation (deskConditionsNote; same pattern as MergeCategoryModal, 71a5669d9) -->
                  {{ deskConditionsNote.before
                  }}<a :href="deskUrl" target="_blank" class="underline">desk</a
                  >{{ deskConditionsNote.after }}
                </span>
                <Button
                  :label="__('I understand, add conditions')"
                  variant="subtle"
                  theme="gray"
                  @click="useNewUI = true"
                />
              </div>
              <SlaAssignmentConditions
                :conditions="slaData.condition_json"
                v-if="useNewUI"
              />
            </div>
          </div>
        </div>
        <hr class="my-8" />
        <div>
          <div class="flex flex-col gap-1">
            <span class="text-lg font-semibold text-ink-gray-8">
              {{ __("Valid From") }}
            </span>
            <span class="text-p-sm text-ink-gray-6">
              {{ __("Choose how long this SLA policy will be active.") }}
            </span>
          </div>
          <div class="mt-3.5 flex gap-5 flex-col md:flex-row">
            <div class="w-full space-y-1.5">
              <FormLabel :label="__('From date')" for="from_date" />
              <DatePicker
                v-model="slaData.start_date"
                variant="subtle"
                placeholder="11/01/2025"
                class="w-full"
                id="from_date"
                @change="validateSlaData('start_date')"
                :formatter="(date) => getFormattedDate(date)"
              >
                <template #prefix>
                  <LucideCalendar class="size-4" />
                </template>
              </DatePicker>
              <ErrorMessage :message="slaDataErrors.start_date" />
            </div>
            <div class="w-full space-y-1.5">
              <FormLabel :label="__('To date')" for="to_date" />
              <DatePicker
                v-model="slaData.end_date"
                variant="subtle"
                placeholder="25/12/2025"
                class="w-full"
                id="to_date"
                @change="validateSlaData('end_date')"
                :formatter="(date) => getFormattedDate(date)"
              >
                <template #prefix>
                  <LucideCalendar class="size-4" />
                </template>
              </DatePicker>
              <ErrorMessage :message="slaDataErrors.end_date" />
            </div>
          </div>
        </div>
        <hr class="my-8" />
        <div>
          <div class="flex flex-col gap-1">
            <span class="text-lg font-semibold text-ink-gray-8">
              {{ __("Response and Resolution") }}
            </span>
            <span class="text-p-sm text-ink-gray-6">
              {{
                __(
                  "Add time targets around support milestones like first reply and resolution times."
                )
              }}
            </span>
          </div>
          <div class="mt-5">
            <!-- <div class="flex gap-6">
          <div
            class="flex items-center gap-2"
            @click="onApplySlaForChange(false)"
          >
            <input
              name="apply_sla_for"
              :checked="!slaData.apply_sla_for_resolution"
              type="radio"
            />
            <div class="select-none text-ink-gray-6 text-sm font-medium">
              //// Neoffice — wrapped in __() by the i18n pass inside this block, which upstream
              //// keeps commented out; delete this marker if the block is ever restored
              {{ __("Apply SLA for response time") }}
            </div>
          </div>
          <div
            class="flex items-center gap-2"
            @click="onApplySlaForChange(true)"
          >
            <input
              name="apply_sla_for"
              :checked="slaData.apply_sla_for_resolution"
              type="radio"
            />
            <div class="select-none text-ink-gray-6 text-sm font-medium">
              //// Neoffice — wrapped in __() by the i18n pass inside this block, which upstream
              //// keeps commented out; delete this marker if the block is ever restored
              {{ __("Apply SLA for response time and resolution time") }}
            </div>
          </div>
        </div> -->
            <div class="mt-5">
              <SlaPriorityList />
            </div>
          </div>
        </div>
        <hr class="my-8" />
        <div>
          <div class="flex flex-col gap-1">
            <span class="text-lg font-semibold text-ink-gray-8">
              {{ __("Status Details") }}
            </span>
            <span class="text-p-sm text-ink-gray-6">
              {{
                __(
                  "Set the default status assigned when a ticket is created, and the status to apply when a ticket is reopened. If not specified, the default status from HD Settings will be used."
                )
              }}
            </span>
          </div>
          <div class="mt-5">
            <SlaStatusList />
          </div>
        </div>
        <hr class="my-8" />
        <SlaHolidays />
      </div>
    </template>
  </SettingsLayoutBase>
  <ConfirmDialog
    v-model="showConfirmDialog.show"
    :title="showConfirmDialog.title"
    :message="showConfirmDialog.message"
    :onConfirm="showConfirmDialog.onConfirm"
    :onCancel="() => (showConfirmDialog.show = false)"
  />
</template>

<script setup lang="ts">
import ConfirmDialog from "@/components/ConfirmDialog.vue";
import {
  resetSlaDataErrors,
  slaActiveScreen,
  slaData,
  slaDataErrors,
  validateSlaData,
} from "@/stores/sla";
import { convertToConditions, getFormattedDate } from "@/utils";
import {
  Badge,
  Button,
  Checkbox,
  createResource,
  DatePicker,
  ErrorMessage,
  FormLabel,
  LoadingIndicator,
  Popover,
  Switch,
  toast,
} from "frappe-ui";
//// Neoffice — `computed` added for deskConditionsNote below.
import { computed, inject, nextTick, onMounted, onUnmounted, ref, watch } from "vue";
import SlaAssignmentConditions from "./SlaAssignmentConditions.vue";
import SlaHolidays from "./SlaHolidays.vue";
import SlaPriorityList from "./SlaPriorityList.vue";
import SlaStatusList from "./SlaStatusList.vue";
import { disableSettingModalOutsideClick } from "../settingsModal";
import { useOnboarding } from "frappe-ui/frappe";
import { __ } from "@/translation";
import SettingsLayoutBase from "@/components/layouts/SettingsLayoutBase.vue";
import { SlaPolicyListResourceSymbol } from "@/types";
import { HDServiceLevelAgreement } from "@/types/doctypes";

const { updateOnboardingStep } = useOnboarding("helpdesk");

const showConfirmDialog = ref({
  show: false,
  title: "",
  message: "",
  onConfirm: () => {},
});
const isDirty = ref(false);
const initialData = ref(null);

const useNewUI = ref(true);
const isOldSla = ref(false);

const slaPolicyList = inject(SlaPolicyListResourceSymbol);
const deskUrl = `${window.location.origin}/app/hd-service-level-agreement/${slaActiveScreen.value.data?.name}`;
//// Neoffice — one message, {0} where the desk link goes; the halves are read back from the
//// translation so each language keeps its own word order (see the template).
const deskConditionsNote = computed(() => {
  const [before, after] = __(
    "Conditions for this SLA were created from {0} which are not compatible with this UI, you will need to recreate the conditions here if you want to manage and add new conditions from this UI."
  ).split("{0}");
  return { before, after: after ?? "" };
});

const getSlaData = createResource({
  url: "frappe.client.get",
  params: {
    doctype: "HD Service Level Agreement",
    name: slaActiveScreen.value.data?.name,
  },
  onSuccess(data: HDServiceLevelAgreement) {
    let condition_json;
    try {
      condition_json = JSON.parse(data.condition_json || "[]");
    } catch (error) {
      toast.error(
        //// Neoffice — upstream wrote it in plain English; wrapped so the French catalogue reaches it (same pass as 71a5669d9)
        __("Assignment conditions are invalid or corrupt, recreate the conditions.")
      );
      condition_json = [];
    }

    const newData = {
      ...data,
      loading: false,
      condition_json: condition_json,
    };
    slaData.value = newData;
    slaData.value.apply_sla_for_resolution = true;
    initialData.value = JSON.stringify(newData);
    const conditionsAvailable = slaData.value.condition?.length > 0;
    const conditionsJsonAvailable = slaData.value.condition_json?.length > 0;
    if (conditionsAvailable && !conditionsJsonAvailable) {
      useNewUI.value = false;
      isOldSla.value = true;
    } else {
      useNewUI.value = true;
      isOldSla.value = false;
    }
  },
});

if (slaActiveScreen.value.data && slaActiveScreen.value.fetchData) {
  slaData.value.loading = true;
  getSlaData.submit();
} else {
  disableSettingModalOutsideClick.value = true;
}

const goBack = () => {
  const confirmDialogInfo = {
    show: true,
    title: __("Unsaved changes"),
    message: __(
      "Are you sure you want to go back? Unsaved changes will be lost."
    ),
    onConfirm: goBack,
  };
  if (isDirty.value && !showConfirmDialog.value.show) {
    showConfirmDialog.value = confirmDialogInfo;
    return;
  }
  if (!slaActiveScreen.value.data && !showConfirmDialog.value.show) {
    showConfirmDialog.value = confirmDialogInfo;
    return;
  }
  // Workaround fix for settings modal not closing after going back
  setTimeout(() => {
    slaActiveScreen.value = {
      screen: "list",
      data: null,
      fetchData: true,
    };
  }, 250);
  showConfirmDialog.value.show = false;
};

const saveSla = () => {
  const validationErrors = validateSlaData(undefined, !useNewUI.value);

  if (Object.values(validationErrors).some((error) => error)) {
    toast.error(
      __("Invalid fields, check if all are filled in and values are correct.")
    );
    return;
  }

  if (slaActiveScreen.value.data) {
    if (isOldSla.value && useNewUI.value) {
      showConfirmDialog.value = {
        show: true,
        title: __("Confirm overwrite"),
        message: __(
          "Your old conditions will be overwritten. Are you sure you want to save?"
        ),
        onConfirm: () => {
          updateSla();
          showConfirmDialog.value.show = false;
        },
      };
      return;
    }
    updateSla();
  } else {
    createSla();
  }
};

const createSla = () => {
  const defaultTicketStatus = slaData.value.default_ticket_status
    ? slaData.value.default_ticket_status?.value
    : null;
  const ticketReopenStatus = slaData.value.reopen_ticket_status
    ? slaData.value.reopen_ticket_status?.value
    : null;
  slaPolicyList?.insert.submit(
    {
      ...slaData.value,
      default_ticket_status: defaultTicketStatus,
      ticket_reopen_status: ticketReopenStatus,
      condition: convertToConditions({
        conditions: slaData.value.condition_json,
        fieldPrefix: "doc",
      }),
      condition_json: JSON.stringify(slaData.value.condition_json),
    },
    {
      onSuccess(data) {
        toast.success(__("SLA policy created successfully."));
        slaActiveScreen.value.data = data;
        slaActiveScreen.value.screen = "view";
        getSlaData.submit({
          doctype: "HD Service Level Agreement",
          name: data.name,
        });
        updateOnboardingStep("setup_sla", true);
      },
    }
  );
};

const updateSla = () => {
  const defaultTicketStatus = slaData.value.default_ticket_status
    ? slaData.value.default_ticket_status?.value
    : null;
  const ticketReopenStatus = slaData.value.reopen_ticket_status
    ? slaData.value.reopen_ticket_status?.value
    : null;
  slaPolicyList?.setValue.submit(
    {
      ...slaData.value,
      name: slaActiveScreen.value.data?.name,
      default_ticket_status: defaultTicketStatus,
      ticket_reopen_status: ticketReopenStatus,
      condition: useNewUI.value
        ? convertToConditions({
            conditions: slaData.value.condition_json,
            fieldPrefix: "doc",
          })
        : slaData.value.condition,
      condition_json: useNewUI.value
        ? JSON.stringify(slaData.value.condition_json)
        : null,
    },
    {
      onSuccess() {
        getSlaData.submit();
        toast.success(__("SLA policy updated successfully."));
        slaPolicyList.reload();
      },
    }
  );
};

const toggleEnabled = () => {
  if (slaData.value.default_sla) {
    toast.error(__("SLA set as default cannot be disabled"));
    return;
  }
  slaData.value.enabled = !slaData.value.enabled;
};

const toggleDefaultSla = () => {
  slaData.value.default_sla = !slaData.value.default_sla;
  if (slaData.value.default_sla) {
    slaData.value.enabled = true;
  }
};

const onApplySlaForChange = (applyForResolution: boolean) => {
  slaData.value.apply_sla_for_resolution = applyForResolution;
  nextTick(() => {
    validateSlaData("priorities");
  });
};

watch(
  slaData,
  (newVal) => {
    if (!initialData.value) return;
    isDirty.value = JSON.stringify(newVal) != initialData.value;
    if (isDirty.value) {
      disableSettingModalOutsideClick.value = true;
    } else {
      disableSettingModalOutsideClick.value = false;
    }
  },
  { deep: true }
);

const beforeUnloadHandler = (event) => {
  if (!isDirty.value) return;
  event.preventDefault();
  event.returnValue = true;
};
onMounted(() => {
  addEventListener("beforeunload", beforeUnloadHandler);
});

onUnmounted(() => {
  removeEventListener("beforeunload", beforeUnloadHandler);
  resetSlaDataErrors();
  disableSettingModalOutsideClick.value = false;
});
</script>
