<template>
  <div class="rounded-md border px-2 border-outline-gray-2 text-sm">
    <div
      class="grid p-2 px-4 items-center"
      :style="{
        gridTemplateColumns,
      }"
      v-if="slaData.priorities?.length !== 0"
    >
      <div
        v-for="column in columns"
        :key="column.key"
        class="text-ink-gray-5 overflow-hidden whitespace-nowrap text-ellipsis"
        :class="{
          'ms-2':
            column.key === 'priority' ||
            column.key === 'response_time' ||
            column.key === 'resolution_time',
        }"
      >
        {{ column.label }}
        <span v-if="column.isRequired" class="text-ink-red-3">*</span>
      </div>
    </div>
    <hr v-if="slaData.priorities?.length !== 0" />
    <SlaPriorityListItem
      v-for="(row, index) in slaData.priorities"
      :key="row.priority"
      :row="row"
      :columns="columns"
      :isLast="index === slaData.priorities.length - 1"
    />
    <!-- //// Neoffice — wrapped in __() so the French catalogue can translate it; upstream showed it in English on every non-English site (71a5669d9 "fix(i18n): 341 visible strings of the SPA never went through __()") -->
    <div
      v-if="slaData.priorities?.length === 0"
      class="text-center p-4 text-ink-gray-5"
    >
      <!-- //// Neoffice — see the block marker above: __() i18n wrap -->
      {{ __("No priorities in the list") }}
    </div>
  </div>
  <div
    class="flex items-center justify-between mt-2.5"
    v-if="
      slaData.priorities.length !== priorityOptions.length ||
      slaDataErrors.default_priority ||
      slaDataErrors.priorities
    "
  >
    <div>
      <!-- //// Neoffice — wrapped in __() so the French catalogue can translate it; upstream showed it in English on every non-English site (71a5669d9 "fix(i18n): 341 visible strings of the SPA never went through __()") -->
      <Button
        v-if="slaData.priorities.length !== priorityOptions.length"
        variant="subtle"
        :label="__('Add row')"
        @click="addRow"
        icon-left="plus"
      />
    </div>
    <ErrorMessage
      :message="slaDataErrors.default_priority || slaDataErrors.priorities"
    />
  </div>
</template>

<script setup lang="ts">
import {
  slaActiveScreen,
  slaData,
  slaDataErrors,
  validateSlaData,
} from "@/stores/sla";
import { getGridTemplateColumnsForTable } from "@/utils";
import { watchDebounced } from "@vueuse/core";
import { Button, createResource, toast } from "frappe-ui";
import { computed, provide, reactive } from "vue";
import SlaPriorityListItem from "./SlaPriorityListItem.vue";
//// Neoffice — added: __() import for the i18n pass below (71a5669d9 "fix(i18n): 341 visible strings of the SPA never went through __()")
import { __ } from "@/translation";

createResource({
  url: "frappe.client.get_list",
  params: {
    doctype: "HD Ticket Priority",
    fields: ["name"],
    filters: {
      disabled: 0,
    },
    order_by: "integer_value desc",
  },
  auto: true,
  onSuccess(data) {
    priorityOptions.push(
      ...data.map((p) => {
        return {
          label: p.name,
          value: p.name,
        };
      })
    );
    if (!slaActiveScreen.value.data) {
      slaData.value.priorities = priorityOptions.map((p, index) => {
        return {
          priority: p.value,
          resolution_time: 60 * 60,
          response_time: 60 * 60,
          default_priority: index === 0,
        };
      });
    }
  },
});

const priorityOptions = reactive([]);

provide("priorityOptions", priorityOptions);

const addRow = () => {
  const existingPriorities = slaData.value.priorities.map((p) => p.priority);
  const availablePriorities = priorityOptions.filter(
    (p) => !existingPriorities.includes(p.value)
  );

  if (availablePriorities.length === 0) {
    //// Neoffice — upstream wrote it in plain English; wrapped so the French catalogue reaches it (same pass as 71a5669d9)
    toast.error(__("All available priorities have already been added"));
    return;
  }

  const newPriority = availablePriorities[0].value;

  slaData.value.priorities.push({
    priority: newPriority,
    resolution_time: 60 * 60,
    response_time: 60 * 60,
    default_priority: slaData.value.priorities.length === 0,
  });
};

//// Neoffice ▼▼▼ — wrapped in __() so the French catalogue can translate these SLA column labels; upstream showed them in English on every non-English site (71a5669d9 "fix(i18n): 341 visible strings of the SPA never went through __()")
const columns = computed(() => [
  {
    label: __('Priority'),
    key: "priority",
    isRequired: true,
  },
  {
    //// Neoffice — see the block marker above: __() i18n wrap
    label: __('Default priority'),
    key: "default_priority",
    isRequired: true,
  },
  {
    //// Neoffice — see the block marker above: __() i18n wrap
    label: __('First response time'),
    key: "response_time",
    isRequired: true,
  },
  {
    //// Neoffice — see the block marker above: __() i18n wrap
    label: __('Resolution time'),
    key: "resolution_time",
    isRequired: true,
  },
  //// Neoffice ▲▲▲
  //   slaData.value.apply_sla_for_resolution && {
  //     label: __('Resolution time'),
  //     key: "resolution_time",
  //     isRequired: Boolean(slaData.value.apply_sla_for_resolution),
  //   },
  // ].filter((c) => c)
]);

const gridTemplateColumns = computed(() => {
  // return getGridTemplateColumnsForTable(columns.value.filter((c) => c));
  return getGridTemplateColumnsForTable(columns.value);
});

provide("gridTemplateColumns", gridTemplateColumns);

watchDebounced(
  () => [...slaData.value.priorities],
  () => {
    validateSlaData("priorities");
  },
  { deep: true, debounce: 300 }
);
</script>
